def transform(grid):
    from collections import Counter

    h, w = len(grid), len(grid[0])
    background = Counter(x for row in grid for x in row).most_common(1)[0][0]

    # Uniform lines in a non-background color are tile dividers.
    sep_rows = [r for r in range(h)
                if len(set(grid[r])) == 1 and grid[r][0] != background]
    sep_cols = [c for c in range(w)
                if len({grid[r][c] for r in range(h)}) == 1
                and grid[0][c] != background]

    def ranges(n, separators):
        cuts = [-1] + separators + [n]
        return [(cuts[i] + 1, cuts[i + 1])
                for i in range(len(cuts) - 1)
                if cuts[i + 1] > cuts[i] + 1]

    row_ranges = ranges(h, sep_rows)
    col_ranges = ranges(w, sep_cols)

    # Record every non-background pattern cell within a tile.
    pattern = {}
    for r0, r1 in row_ranges:
        for c0, c1 in col_ranges:
            for r in range(r0, r1):
                for c in range(c0, c1):
                    color = grid[r][c]
                    if color != background:
                        pattern[(r - r0, c - c0)] = color

    out = [row[:] for row in grid]
    for r0, r1 in row_ranges:
        for c0, c1 in col_ranges:
            for (dr, dc), color in pattern.items():
                if r0 + dr < r1 and c0 + dc < c1:
                    out[r0 + dr][c0 + dc] = color
    return out
